import sys

def can_blend_all_colors(s):
    n = len(s)
    has_A = [False] * n
    has_B = [False] * n
    has_C = [False] * n

    for i in range(n):
        if s[i] == 'A':
            has_A[i] = True
            if i > 0:
                has_A[i - 1] = True
            if i < n - 1:
                has_A[i + 1] = True
        if s[i] == 'B':
            has_B[i] = True
            if i > 0:
                has_B[i - 1] = True
            if i < n - 2:
                has_B[i + 1] = True
        if s[i] == 'C':
            has_C[i] = True
            if i > 0:
                has_C[i - 1] = True
            if i < n - 3:
                has_C[i + 1] = True

    for i in range(n):
        if has_A[i] and has_B[i] and has_C[i]:
            return "Yes"

    return "No"

input = sys.stdin.read().strip()
print(can_blend_all_colors(input))
